"use client"

/** @responsibility Coordinates the shared layout document, change events, and layout actions for one application shell. */

import * as React from "react"

import { cn } from "@/lib/utils"
import {
  closePane,
  createAppShellLayout,
  focusPane,
  maximizePane,
  resetPaneSizes,
  resizeDock,
  normalizeAppShellLayout,
  restorePane,
  setDockOpen,
  splitPane,
  toggleDock,
  type AppShellDockSide,
  type AppShellLayout,
  type LayoutNode,
  type LayoutNodeId,
  type PaneSplitDirection,
  type PaneViewId,
} from "@/lib/app-shell-layout"

/** Primary modifier choices supported by the maximize keyboard shortcut. */
type AppShellShortcutModifier = "control" | "meta" | "mod"

/** Describes one exact keyboard shortcut for toggling pane maximize. */
interface AppShellKeyboardShortcut {
  /** KeyboardEvent key, matched without case sensitivity. */
  key: string
  /**
   * Primary modifier. `mod` accepts exactly one of Meta or Control; omit
   * for neither.
   * @defaultValue undefined
   */
  modifier?: AppShellShortcutModifier
  /**
   * Whether Alt must be pressed.
   * @defaultValue false
   */
  altKey?: boolean
  /**
   * Whether Shift must be pressed.
   * @defaultValue false
   */
  shiftKey?: boolean
  /**
   * Prevents the matched browser event by default. Set false to keep it.
   * @defaultValue true
   */
  preventDefault?: boolean
}

/** The out-of-the-box maximize shortcut: Shift+Escape, as in Zed. */
const DEFAULT_MAXIMIZE_SHORTCUT: AppShellKeyboardShortcut = Object.freeze({
  key: "Escape",
  shiftKey: true,
})

/** Keyboard events already claimed by one shell's shortcut handler. */
const handledShortcutEvents = new WeakSet<KeyboardEvent>()

/**
 * Checks whether a keyboard event carries exactly the requested primary
 * modifier (Control / Meta), and no unrequested one.
 *
 * @param event - The keyboard event being checked.
 * @param modifier - The required primary modifier, or undefined for none.
 * @returns Whether the event satisfies the requested modifier.
 */
function matchesShortcutModifier(
  event: KeyboardEvent,
  modifier: AppShellShortcutModifier | undefined,
) {
  switch (modifier) {
    case "mod":
      return event.metaKey !== event.ctrlKey
    case "meta":
      return event.metaKey && !event.ctrlKey
    case "control":
      return event.ctrlKey && !event.metaKey
    case undefined:
      return !event.metaKey && !event.ctrlKey
    default: {
      const exhaustiveModifier: never = modifier
      return exhaustiveModifier
    }
  }
}

/**
 * Checks whether a keyboard event comes from a place where the user is
 * typing text, so plain single-character shortcuts never steal keystrokes.
 *
 * @param event - The keyboard event being checked.
 * @returns Whether the event target consumes plain keystrokes for editing.
 */
function isEditableShortcutTarget(event: KeyboardEvent) {
  const target = event.target

  if (!(target instanceof HTMLElement)) return false

  return (
    target.isContentEditable ||
    target instanceof HTMLInputElement ||
    target instanceof HTMLTextAreaElement ||
    target instanceof HTMLSelectElement
  )
}

/** Operations that can produce a layout change. */
type AppShellLayoutOperation =
  | "pane-resize"
  | "dock-resize"
  | "dock-toggle"
  | "split"
  | "close"
  | "focus"
  | "maximize"
  | "restore"
  | "reset"
  | "set"

/** Context accompanying every AppShell layout notification. */
interface AppShellChangeMeta {
  /** The operation that produced the change. */
  operation: AppShellLayoutOperation
  /**
   * Whether the change is a live step of an ongoing gesture or a settled
   * result. Persist settled layouts; live layouts fire on every pointer move.
   */
  phase: "live" | "settled"
}

/** Shared state and the single mutation path for one AppShell. */
interface AppShellContextValue {
  /** The layout document currently rendered. */
  layout: AppShellLayout
  /** Applies a pure layout update and publishes the resulting document. */
  updateLayout: (
    updater: (layout: AppShellLayout) => AppShellLayout,
    meta: AppShellChangeMeta,
  ) => void
}

const AppShellContext = React.createContext<AppShellContextValue | null>(null)

/**
 * Reads the layout context of the nearest AppShell.
 *
 * @returns The current AppShell context value.
 * @throws When called outside an AppShell.
 */
function useAppShellContext(): AppShellContextValue {
  const context = React.useContext(AppShellContext)

  if (!context) {
    throw new Error("AppShell components must be used within an AppShell.")
  }

  return context
}

/**
 * Collects every node id in a workspace tree.
 *
 * @param node - The subtree root to walk.
 * @param ids - The accumulator receiving each id.
 * @returns The accumulator holding every node id.
 */
function collectNodeIds(node: LayoutNode, ids = new Set<string>()): Set<string> {
  ids.add(node.id)

  if (node.type === "split") {
    for (const child of node.children) {
      collectNodeIds(child, ids)
    }
  }

  return ids
}

/**
 * Derives the next generated pane id of the form "pane-N": one past the
 * highest generated number currently in the tree, so ids read sequentially
 * regardless of how many internal split nodes exist.
 *
 * @param layout - The current layout document.
 * @returns A pane id unused by any node in the workspace.
 */
function nextPaneId(layout: AppShellLayout): LayoutNodeId {
  const ids = collectNodeIds(layout.workspace.root)
  let highest = 0

  for (const id of ids) {
    const match = /^pane-(\d+)$/.exec(id)

    if (match) {
      highest = Math.max(highest, Number(match[1]))
    }
  }

  let index = highest + 1

  while (ids.has(`pane-${index}`) || ids.has(`split:pane-${index}`)) {
    index++
  }

  return `pane-${index}`
}

/** Values accepted by the `splitPane` action. */
interface SplitPaneActionOptions {
  /** The pane to split. Defaults to the active pane. */
  paneId?: LayoutNodeId
  /** Where the new pane lands relative to the split pane. */
  direction: PaneSplitDirection
  /** Views hosted by the new pane. */
  views?: readonly PaneViewId[]
  /** The view the new pane presents. Defaults to the first provided view. */
  activeViewId?: PaneViewId
  /** Unique id for the new pane. Defaults to a generated "pane-N" id. */
  newPaneId?: LayoutNodeId
}

/** Imperative layout actions bound to the nearest AppShell. */
interface UseAppShellResult {
  /** The layout document currently rendered. */
  layout: AppShellLayout
  /**
   * Splits a pane and focuses the new pane. Returns the new pane's id, or
   * null when the split was rejected (unknown target or duplicate id).
   */
  splitPane: (options: SplitPaneActionOptions) => LayoutNodeId | null
  /** Closes a pane. The last remaining pane never closes. */
  closePane: (options?: { paneId?: LayoutNodeId }) => void
  /** Focuses a pane. */
  focusPane: (options: { paneId: LayoutNodeId }) => void
  /** Maximizes a pane over the workspace. Defaults to the active pane. */
  maximizePane: (options?: { paneId?: LayoutNodeId }) => void
  /** Restores a maximized workspace. */
  restorePane: () => void
  /** Opens or closes one dock. */
  setDockOpen: (options: { side: AppShellDockSide; open: boolean }) => void
  /** Reverses one dock's visibility. */
  toggleDock: (options: { side: AppShellDockSide }) => void
  /** Resizes one dock in pixels. */
  resizeDock: (options: {
    side: AppShellDockSide
    size: number
    minSize?: number
    maxSize?: number
  }) => void
  /** Resets every split to evenly distributed weights. */
  resetPaneSizes: () => void
  /** Replaces the whole layout document, for example from persistence. */
  setLayout: (layout: AppShellLayout) => void
}

/**
 * Provides the layout document and imperative layout actions of the nearest
 * AppShell.
 *
 * @returns The current layout and settled layout actions.
 * @throws When called outside an AppShell.
 */
function useAppShell(): UseAppShellResult {
  const { layout, updateLayout } = useAppShellContext()

  const actions = React.useMemo(() => {
    /**
     * Applies one settled layout operation.
     *
     * @param operation - The operation label published with the change.
     * @param updater - The pure layout update to apply.
     */
    const settle = (
      operation: AppShellLayoutOperation,
      updater: (current: AppShellLayout) => AppShellLayout,
    ) => {
      updateLayout(updater, { operation, phase: "settled" })
    }

    return {
      splitPane: (options: SplitPaneActionOptions) => {
        let newPaneId: LayoutNodeId | null = null

        updateLayout(
          (current) => {
            const paneId = options.newPaneId ?? nextPaneId(current)
            const next = splitPane(current, {
              paneId: options.paneId ?? current.workspace.activePaneId,
              direction: options.direction,
              newPaneId: paneId,
              views: options.views,
              activeViewId: options.activeViewId,
            })

            newPaneId = next === current ? null : paneId

            return next
          },
          { operation: "split", phase: "settled" },
        )

        return newPaneId
      },
      closePane: (options?: { paneId?: LayoutNodeId }) =>
        settle("close", (current) =>
          closePane(current, {
            paneId: options?.paneId ?? current.workspace.activePaneId,
          }),
        ),
      focusPane: (options: { paneId: LayoutNodeId }) =>
        settle("focus", (current) => focusPane(current, options)),
      maximizePane: (options?: { paneId?: LayoutNodeId }) =>
        settle("maximize", (current) => maximizePane(current, options)),
      restorePane: () => settle("restore", restorePane),
      setDockOpen: (options: { side: AppShellDockSide; open: boolean }) =>
        settle("dock-toggle", (current) => setDockOpen(current, options)),
      toggleDock: (options: { side: AppShellDockSide }) =>
        settle("dock-toggle", (current) => toggleDock(current, options)),
      resizeDock: (options: {
        side: AppShellDockSide
        size: number
        minSize?: number
        maxSize?: number
      }) => settle("dock-resize", (current) => resizeDock(current, options)),
      resetPaneSizes: () => settle("reset", resetPaneSizes),
      setLayout: (next: AppShellLayout) =>
        settle("set", () => normalizeAppShellLayout(next)),
    }
  }, [updateLayout])

  return React.useMemo(
    () => ({ layout, ...actions }),
    [actions, layout],
  )
}

/** Properties accepted by the AppShell root. */
interface AppShellProps extends React.ComponentProps<"div"> {
  /**
   * The layout document when the shell is controlled by its consumer.
   * Interactions report documents through `onLayoutChange`; the consumer
   * renders them back through this property.
   */
  layout?: AppShellLayout
  /**
   * Initial layout for an uncontrolled shell.
   * @defaultValue createAppShellLayout()
   */
  defaultLayout?: AppShellLayout
  /**
   * Called with the next document on every step of an interaction, including
   * each pointer move of a resize. Persist from `onLayoutCommit` instead.
   */
  onLayoutChange?: (layout: AppShellLayout, meta: AppShellChangeMeta) => void
  /** Called once per settled operation with the resulting document. */
  onLayoutCommit?: (layout: AppShellLayout, meta: AppShellChangeMeta) => void
  /**
   * Keyboard shortcut that toggles maximize on the active pane. Pass a
   * shortcut description to override it, or false to turn it off.
   * @defaultValue Shift+Escape
   */
  maximizeShortcut?: AppShellKeyboardShortcut | false
}

/**
 * Provides the application-shell frame: a full-height column that hosts the
 * header, body (docks plus workspace), and status bar, and coordinates one
 * shared layout document.
 *
 * The shell owns presentation only. Persistence belongs to the consuming
 * application: read documents from `onLayoutCommit` and supply them back via
 * `layout` or `defaultLayout`.
 *
 * @param props - Controlled or uncontrolled layout, change callbacks, and
 * native container properties.
 * @returns A context provider and the shell's outer frame.
 */
function AppShell({
  layout: layoutProp,
  defaultLayout,
  onLayoutChange,
  onLayoutCommit,
  maximizeShortcut = DEFAULT_MAXIMIZE_SHORTCUT,
  className,
  children,
  ref,
  ...props
}: AppShellProps) {
  const [fallbackLayout] = React.useState(() =>
    createAppShellLayout(),
  )
  const [internalLayout, setInternalLayout] = React.useState<
    AppShellLayout | undefined
  >(defaultLayout)

  const providedLayout = layoutProp ?? internalLayout ?? fallbackLayout
  // Provided documents (persisted, hand-built, or migrated) are normalized
  // before rendering so healed pointers and tree invariants always hold.
  const layout = React.useMemo(
    () => normalizeAppShellLayout(providedLayout),
    [providedLayout],
  )
  const layoutRef = React.useRef(layout)
  layoutRef.current = layout
  const lastCommittedRef = React.useRef(layout)
  const rootRef = React.useRef<HTMLDivElement>(null)
  // Serves both our shortcut-scoping ref and a consumer's ref; memoized so
  // React does not detach and re-attach refs on every render.
  const composedRootRef = React.useMemo(
    () => (element: HTMLDivElement | null) => {
      rootRef.current = element
      if (typeof ref === "function") ref(element)
      else if (ref) ref.current = element
    },
    [ref],
  )

  const controlled = layoutProp !== undefined

  const updateLayout = React.useCallback<AppShellContextValue["updateLayout"]>(
    (updater, meta) => {
      const current = layoutRef.current
      const next = updater(current)

      if (next !== current) {
        layoutRef.current = next

        if (!controlled) {
          setInternalLayout(next)
        }

        onLayoutChange?.(next, meta)
      }

      // A settled operation commits only when the document differs from the
      // last committed one, so no-op operations produce no phantom commits
      // while gesture-ending calls still deliver the final document.
      if (meta.phase === "settled" && next !== lastCommittedRef.current) {
        lastCommittedRef.current = next
        onLayoutCommit?.(next, meta)
      }
    },
    [controlled, onLayoutChange, onLayoutCommit],
  )

  const shortcut = maximizeShortcut === false ? undefined : maximizeShortcut
  const shortcutKey = shortcut?.key
  const shortcutModifier = shortcut?.modifier
  const shortcutAltKey = Boolean(shortcut?.altKey)
  const shortcutShiftKey = Boolean(shortcut?.shiftKey)
  const shortcutPreventsDefault = shortcut?.preventDefault !== false

  React.useEffect(() => {
    if (!shortcutKey) return

    /**
     * Toggles maximize on the active pane when the pressed keys exactly
     * match the configured shortcut.
     *
     * @param event - The global keyboard event being checked.
     */
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.defaultPrevented || event.repeat || event.isComposing) return
      if (handledShortcutEvents.has(event)) return
      // A bare single-character shortcut must not fire while the user is
      // typing in a text field. Named keys such as Escape are always safe.
      if (
        shortcutModifier === undefined &&
        shortcutKey.length === 1 &&
        isEditableShortcutTarget(event)
      ) {
        return
      }
      // Only this shell's own keystrokes count, so two shells on one page
      // never fight over the shortcut. When nothing is focused (the event
      // lands on the page body), the first shell handles it.
      const root = rootRef.current
      const target = event.target
      const insideShell =
        root !== null && target instanceof Node && root.contains(target)
      const nothingFocused =
        !(target instanceof HTMLElement) ||
        target === target.ownerDocument.body ||
        target === target.ownerDocument.documentElement

      if (!insideShell && !nothingFocused) return

      const matches =
        event.key.toLowerCase() === shortcutKey.toLowerCase() &&
        matchesShortcutModifier(event, shortcutModifier) &&
        event.altKey === shortcutAltKey &&
        event.shiftKey === shortcutShiftKey

      if (!matches) return

      handledShortcutEvents.add(event)
      if (shortcutPreventsDefault) event.preventDefault()

      const maximized =
        layoutRef.current.workspace.maximizedPaneId !== undefined

      updateLayout(
        (current) =>
          maximized ? restorePane(current) : maximizePane(current, {}),
        { operation: maximized ? "restore" : "maximize", phase: "settled" },
      )
    }

    window.addEventListener("keydown", handleKeyDown)
    return () => window.removeEventListener("keydown", handleKeyDown)
  }, [
    shortcutAltKey,
    shortcutKey,
    shortcutModifier,
    shortcutPreventsDefault,
    shortcutShiftKey,
    updateLayout,
  ])

  const contextValue = React.useMemo<AppShellContextValue>(
    () => ({ layout, updateLayout }),
    [layout, updateLayout],
  )

  return (
    <AppShellContext.Provider value={contextValue}>
      {/* Consumer props spread first so the attributes the shell owns
          (slot, ref) always win. */}
      <div
        {...props}
        ref={composedRootRef}
        data-slot="app-shell"
        className={cn(
          "flex h-full min-h-0 w-full flex-col overflow-hidden bg-background font-sans text-foreground",
          className,
        )}
      >
        {children}
      </div>
    </AppShellContext.Provider>
  )
}

export {
  AppShell,
  useAppShell,
  useAppShellContext,
  type AppShellChangeMeta,
  type AppShellContextValue,
  type AppShellKeyboardShortcut,
  type AppShellLayoutOperation,
  type AppShellProps,
  type AppShellShortcutModifier,
  type SplitPaneActionOptions,
  type UseAppShellResult,
}

/** @responsibility Renders the static frame regions of the shell: header, body row, main column, and status bar. */

import * as React from "react"

import { cn } from "@/lib/utils"

/**
 * Renders the shell's top chrome region.
 *
 * @param props - Native header properties.
 * @returns A fixed-height header row above the shell body.
 */
function AppShellHeader({
  className,
  ...props
}: React.ComponentProps<"header">) {
  return (
    <header
      data-slot="app-shell-header"
      className={cn(
        "flex h-12 shrink-0 items-center gap-2 border-b border-border px-3",
        className,
      )}
      {...props}
    />
  )
}

/**
 * Renders the shell's middle row hosting the docks and the main column.
 *
 * @param props - Native container properties.
 * @returns A flexible row between the header and status bar.
 */
function AppShellBody({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="app-shell-body"
      className={cn("flex min-h-0 w-full flex-1", className)}
      {...props}
    />
  )
}

/**
 * Renders the shell's center column hosting the workspace and bottom dock.
 *
 * @param props - Native container properties.
 * @returns A flexible column between the left and right docks.
 */
function AppShellMain({ className, ...props }: React.ComponentProps<"main">) {
  return (
    <main
      data-slot="app-shell-main"
      className={cn("flex min-h-0 min-w-0 flex-1 flex-col", className)}
      {...props}
    />
  )
}

/**
 * Renders the shell's bottom status region.
 *
 * @param props - Native container properties.
 * @returns A fixed-height status row below the shell body.
 */
function AppShellStatusBar({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="app-shell-status-bar"
      className={cn(
        "flex h-8 shrink-0 items-center gap-2 border-t border-border px-3 text-xs text-muted-foreground",
        className,
      )}
      {...props}
    />
  )
}

export { AppShellBody, AppShellHeader, AppShellMain, AppShellStatusBar }

"use client"

/** @responsibility Renders one fixed, pixel-sized, resizable dock slot around the workspace. */

import * as React from "react"

import { cn } from "@/lib/utils"
import {
  AppShellDockSide,
  resizeDock,
  type AppShellLayout,
} from "@/lib/app-shell-layout"

import { useAppShellContext } from "./app-shell"

const DEFAULT_DOCK_MIN_SIZE = 120
const DEFAULT_DOCK_MAX_SIZE = 640
const DOCK_KEYBOARD_RESIZE_STEP = 16

/** State snapshotted for the lifetime of one dock resize gesture. */
interface DockDragState {
  pointerId: number
  startX: number
  startY: number
  startSize: number
  /** The most recent size the gesture produced, settled on release. */
  latestSize: number
  rightToLeft: boolean
  changed: boolean
}

/** Properties accepted by one AppShell dock. */
interface AppShellDockProps extends React.ComponentProps<"aside"> {
  /** The dock slot this element occupies. */
  side: AppShellDockSide
  /**
   * Smallest pixel extent while resizing.
   * @defaultValue 120
   */
  minSize?: number
  /**
   * Largest pixel extent while resizing.
   * @defaultValue 640
   */
  maxSize?: number
  /**
   * Whether the dock presents its resize separator.
   * @defaultValue true
   */
  resizable?: boolean
  /**
   * Accessible name of the dock's resize separator. Override it to localize
   * or reword what screen readers announce.
   * @defaultValue "Resize left dock" (matching the side)
   */
  resizeHandleLabel?: string
}

/**
 * Resolves the default accessible name for one dock side.
 *
 * @param side - The dock slot.
 * @returns A capitalized, human-readable dock name.
 */
function dockLabel(side: AppShellDockSide): string {
  return `${side.charAt(0).toUpperCase()}${side.slice(1)} dock`
}

/**
 * Works out the dock's new pixel size while its handle is being dragged.
 * Each dock grows when the pointer moves away from its home edge:
 *
 * ```txt
 *   ┌──────┬───────────────┬──────┐
 *   │ left ▸│    center    │◂ right│     ▸ drag right = left grows
 *   │      │               │      │      ◂ drag left  = right grows
 *   ├──────┴───────▴───────┴──────┤      ▴ drag up    = bottom grows
 *   │            bottom           │
 *   └─────────────────────────────┘
 * ```
 *
 * In right-to-left writing mode the left/right directions flip with it.
 *
 * @param side - The dock slot being resized.
 * @param dragState - The gesture's starting snapshot.
 * @param event - The current pointer event.
 * @returns The proposed pixel size before clamping.
 */
function dockSizeForPointer(
  side: AppShellDockSide,
  dragState: DockDragState,
  event: React.PointerEvent<HTMLElement>,
): number {
  if (side === AppShellDockSide.Bottom) {
    return dragState.startSize - (event.clientY - dragState.startY)
  }

  const along =
    (event.clientX - dragState.startX) * (dragState.rightToLeft ? -1 : 1)

  return side === AppShellDockSide.Left
    ? dragState.startSize + along
    : dragState.startSize - along
}

/**
 * Renders one dock slot: a fixed, pixel-sized region beside or below the
 * workspace with an accessible resize separator on its inner edge. Dock
 * pixel sizes are intentionally outside the workspace's weighted tree so a
 * dock keeps its extent when the window resizes.
 *
 * Dock visibility and size live in the shell's layout document; a closed
 * dock renders nothing while retaining its size for reopening.
 *
 * @param props - The dock side, resize bounds, and native properties.
 * @returns The dock element, or null while the dock is closed.
 */
function AppShellDock({
  side,
  minSize = DEFAULT_DOCK_MIN_SIZE,
  maxSize = DEFAULT_DOCK_MAX_SIZE,
  resizable = true,
  resizeHandleLabel,
  className,
  style,
  children,
  id: idProp,
  "aria-label": ariaLabel,
  ...props
}: AppShellDockProps) {
  const { layout, updateLayout } = useAppShellContext()
  const dragStateRef = React.useRef<DockDragState | null>(null)
  const [resizing, setResizing] = React.useState(false)
  const generatedId = React.useId()
  const dockId = idProp ?? generatedId

  const dock = layout.docks[side]
  const bottom = side === AppShellDockSide.Bottom
  const size = Math.min(maxSize, Math.max(minSize, dock.size))

  /**
   * Applies one dock resize through the shared layout document.
   *
   * @param nextSize - The proposed pixel size.
   * @param phase - Whether the gesture is ongoing or settled.
   */
  const applyResize = (nextSize: number, phase: "live" | "settled") => {
    updateLayout(
      (current: AppShellLayout) =>
        resizeDock(current, { side, size: nextSize, minSize, maxSize }),
      { operation: "dock-resize", phase },
    )
  }

  /**
   * Ends a resize gesture. Runs for pointer up, cancel, and lost capture;
   * whichever arrives first wins. The gesture's own last size is settled —
   * not whatever happens to be rendered — so consumers persisting settled
   * events always get the final value, even when the ending event carries
   * no usable coordinates or a re-render is still catching up.
   *
   * @param event - The pointer event ending the gesture.
   */
  const finishResize = (event: React.PointerEvent<HTMLElement>) => {
    const dragState = dragStateRef.current

    if (!dragState || dragState.pointerId !== event.pointerId) return

    dragStateRef.current = null
    setResizing(false)

    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId)
    }

    if (dragState.changed) {
      applyResize(dragState.latestSize, "settled")
    }
  }

  if (!dock.open) {
    return null
  }

  return (
    // Consumer props spread first so the attributes the dock owns
    // (id, slot, side, sizing style) always win.
    <aside
      {...props}
      id={dockId}
      data-slot="app-shell-dock"
      data-side={side}
      aria-label={ariaLabel ?? dockLabel(side)}
      className={cn(
        "relative flex shrink-0 flex-col overflow-hidden bg-sidebar text-sidebar-foreground",
        side === AppShellDockSide.Left && "border-e border-border",
        side === AppShellDockSide.Right && "border-s border-border",
        bottom && "w-full border-t border-border",
        className,
      )}
      style={{
        ...style,
        ...(bottom ? { height: size } : { width: size }),
      }}
    >
      {children}
      {resizable ? (
        <div
          role="separator"
          tabIndex={0}
          aria-label={
            resizeHandleLabel ?? `Resize ${dockLabel(side).toLowerCase()}`
          }
          aria-controls={dockId}
          aria-orientation={bottom ? "horizontal" : "vertical"}
          aria-valuenow={size}
          aria-valuemin={minSize}
          aria-valuemax={maxSize}
          data-slot="app-shell-dock-separator"
          data-side={side}
          data-resizing={resizing || undefined}
          className={cn(
            // The dock clips its overflow, so the grab target sits fully
            // inside the inner edge; the border remains the visible line.
            "absolute z-10 bg-transparent outline-none transition-colors select-none touch-none",
            "hover:bg-ring/60 data-resizing:bg-ring",
            "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-0",
            bottom
              ? "inset-x-0 top-0 h-1.5 cursor-row-resize"
              : "inset-y-0 w-1.5 cursor-col-resize",
            side === AppShellDockSide.Left && "end-0",
            side === AppShellDockSide.Right && "start-0",
          )}
          onPointerDown={(event) => {
            if (event.button !== 0 || dragStateRef.current) return

            try {
              event.currentTarget.setPointerCapture(event.pointerId)
            } catch {
              // Synthetic pointer events (tests) have no capturable pointer
              // id; resizing still works through the element's own events.
            }
            dragStateRef.current = {
              pointerId: event.pointerId,
              startX: event.clientX,
              startY: event.clientY,
              startSize: size,
              latestSize: size,
              rightToLeft:
                getComputedStyle(event.currentTarget).direction === "rtl",
              changed: false,
            }
            setResizing(true)
          }}
          onPointerMove={(event) => {
            const dragState = dragStateRef.current

            if (!dragState || dragState.pointerId !== event.pointerId) return

            const nextSize = Math.min(
              maxSize,
              Math.max(minSize, dockSizeForPointer(side, dragState, event)),
            )

            dragState.changed = true
            dragState.latestSize = nextSize
            applyResize(nextSize, "live")
          }}
          onPointerUp={finishResize}
          onPointerCancel={finishResize}
          onLostPointerCapture={finishResize}
          onKeyDown={(event) => {
            const rightToLeft =
              getComputedStyle(event.currentTarget).direction === "rtl"

            let nextSize: number | undefined

            switch (event.key) {
              case "ArrowLeft":
                if (!bottom) {
                  const grow = (side === AppShellDockSide.Right) !== rightToLeft
                  nextSize =
                    size + (grow ? 1 : -1) * DOCK_KEYBOARD_RESIZE_STEP
                }
                break
              case "ArrowRight":
                if (!bottom) {
                  const grow = (side === AppShellDockSide.Left) !== rightToLeft
                  nextSize =
                    size + (grow ? 1 : -1) * DOCK_KEYBOARD_RESIZE_STEP
                }
                break
              case "ArrowUp":
                if (bottom) nextSize = size + DOCK_KEYBOARD_RESIZE_STEP
                break
              case "ArrowDown":
                if (bottom) nextSize = size - DOCK_KEYBOARD_RESIZE_STEP
                break
              case "Home":
                nextSize = minSize
                break
              case "End":
                nextSize = maxSize
                break
            }

            if (nextSize === undefined) return

            event.preventDefault()
            applyResize(nextSize, "settled")
          }}
        />
      ) : null}
    </aside>
  )
}

export { AppShellDock, type AppShellDockProps }

"use client"

/** @responsibility Renders the recursive workspace tree as nested SplitViews and routes pane focus and resizes back to the layout document. */

import * as React from "react"

import { cn } from "@/lib/utils"
import {
  SplitView,
  SplitViewPanel,
  SplitViewSeparator,
  type SplitViewLayout,
  type SplitViewSize,
} from "@/components/split-view"
import {
  findNode,
  setSplitWeights,
  focusPane,
  type LayoutNode,
  type LayoutNodeId,
  type PaneNode,
  type SplitNode,
} from "@/lib/app-shell-layout"

import { useAppShellContext } from "./app-shell"

/** Properties accepted by the workspace region. */
interface AppShellWorkspaceProps
  extends Omit<React.ComponentProps<"div">, "children"> {
  /**
   * Renders the content of one pane. Receives the pane node; resolve its
   * views to application content here. The layout document never holds
   * elements, so panes stay serializable.
   */
  renderPane: (pane: PaneNode) => React.ReactNode
  /**
   * Smallest size of every workspace pane: a percentage number, "Npx", or
   * "N%".
   * @defaultValue "96px"
   */
  minPaneSize?: SplitViewSize
  /**
   * Accessible name of every separator between workspace panes. Override it
   * to localize or reword what screen readers announce.
   * @defaultValue "Resize workspace panes"
   */
  separatorLabel?: string
}

/**
 * Renders one workspace pane shell with focus tracking.
 *
 * @param props - The pane node, active state, and the pane renderer.
 * @returns The pane container hosting application content.
 */
function WorkspacePane({
  pane,
  active,
  renderPane,
}: {
  pane: PaneNode
  active: boolean
  renderPane: AppShellWorkspaceProps["renderPane"]
}) {
  const { updateLayout } = useAppShellContext()

  /** Promotes this pane to the active pane when interaction enters it. */
  const activate = () => {
    if (!active) {
      updateLayout((current) => focusPane(current, { paneId: pane.id }), {
        operation: "focus",
        phase: "settled",
      })
    }
  }

  return (
    <div
      data-slot="app-shell-pane"
      data-pane-id={pane.id}
      data-active={active || undefined}
      className={cn(
        "relative flex h-full min-h-0 min-w-0 flex-1 flex-col overflow-hidden",
        "data-active:ring-1 data-active:ring-inset data-active:ring-ring/40",
      )}
      onFocusCapture={activate}
      onPointerDownCapture={activate}
    >
      {renderPane(pane)}
    </div>
  )
}

/**
 * Renders one node of the workspace tree.
 *
 * Maximizing never removes anything. The other panes are simply rendered at
 * 0% width, so their content (scroll position, typed text, and so on) stays
 * alive and comes back untouched on restore:
 *
 * ```txt
 *   normal      │ A 30% │ B 40% │ C 30% │
 *   maximize B  │         B 100%        │   A and C still mounted, at 0%
 * ```
 *
 * The saved layout document is not touched either — the 100/0 sizes are
 * made up at render time from `maximizedPaneId`.
 *
 * @param props - The node, active and maximized pane ids, the pane
 * renderer, and the minimum pane size.
 * @returns The rendered subtree.
 */
function WorkspaceNode({
  node,
  activePaneId,
  maximizedPaneId,
  renderPane,
  minPaneSize,
  separatorLabel,
}: {
  node: LayoutNode
  activePaneId: LayoutNodeId
  maximizedPaneId: LayoutNodeId | undefined
  renderPane: AppShellWorkspaceProps["renderPane"]
  minPaneSize: SplitViewSize
  separatorLabel: string
}) {
  const { updateLayout } = useAppShellContext()

  if (node.type === "pane") {
    return (
      <WorkspacePane
        pane={node}
        active={node.id === activePaneId}
        renderPane={renderPane}
      />
    )
  }

  const split: SplitNode = node
  // The 100/0 sizing only applies to splits on the path to the maximized
  // pane. Splits inside hidden branches keep their normal proportions —
  // they are invisible anyway, and an all-zero layout would be unusable.
  const maximizing =
    maximizedPaneId !== undefined &&
    findNode(split, maximizedPaneId) !== undefined
  const layout: SplitViewLayout = {}

  for (const child of split.children) {
    layout[child.id] = maximizing
      ? findNode(child, maximizedPaneId) !== undefined
        ? 100
        : 0
      : child.weight * 100
  }

  /**
   * Writes a SplitView percentage layout back as sibling weights.
   *
   * @param next - The SplitView layout produced by an interaction.
   * @param phase - Whether the gesture is ongoing or settled.
   */
  const applyWeights = (next: SplitViewLayout, phase: "live" | "settled") => {
    if (maximizing) {
      return
    }

    updateLayout(
      (current) =>
        setSplitWeights(current, {
          splitId: split.id,
          weights: split.children.map(
            (child) => (next[child.id] ?? child.weight * 100) / 100,
          ),
        }),
      { operation: "pane-resize", phase },
    )
  }

  return (
    <SplitView
      orientation={split.orientation}
      layout={layout}
      onLayoutChange={(next) => applyWeights(next, "live")}
      onLayoutCommit={(next) => applyWeights(next, "settled")}
      className="h-full w-full"
    >
      {split.children.flatMap((child, index) => {
        const hiddenByMaximize = maximizing && layout[child.id] === 0

        const panel = (
          <SplitViewPanel
            key={child.id}
            id={child.id}
            minSize={maximizing ? 0 : minPaneSize}
            // Panes squeezed to zero width stay mounted (their content
            // state survives) but become inert: not tabbable and hidden
            // from screen readers until the workspace is restored.
            inert={hiddenByMaximize || undefined}
          >
            <WorkspaceNode
              node={child}
              activePaneId={activePaneId}
              maximizedPaneId={maximizedPaneId}
              renderPane={renderPane}
              minPaneSize={minPaneSize}
              separatorLabel={separatorLabel}
            />
          </SplitViewPanel>
        )

        if (index === 0) {
          return [panel]
        }

        return [
          <SplitViewSeparator
            key={`separator:${child.id}`}
            aria-label={separatorLabel}
            className={cn(maximizedPaneId !== undefined && "hidden")}
          />,
          panel,
        ]
      })}
    </SplitView>
  )
}

/**
 * Renders the shell's recursive center region. Panes and splits come from
 * the shared layout document; a maximized pane temporarily fills the whole
 * region while the document — and every mounted pane — stays untouched.
 *
 * @param props - The pane renderer, minimum pane size, and native container
 * properties.
 * @returns The workspace region bound to the shell's layout document.
 */
function AppShellWorkspace({
  renderPane,
  minPaneSize = "96px",
  separatorLabel = "Resize workspace panes",
  className,
  ...props
}: AppShellWorkspaceProps) {
  const { layout } = useAppShellContext()
  const { workspace } = layout

  return (
    <div
      data-slot="app-shell-workspace"
      data-maximized={workspace.maximizedPaneId !== undefined || undefined}
      className={cn("relative flex min-h-0 min-w-0 flex-1", className)}
      {...props}
    >
      <WorkspaceNode
        node={workspace.root}
        activePaneId={workspace.activePaneId}
        maximizedPaneId={workspace.maximizedPaneId}
        renderPane={renderPane}
        minPaneSize={minPaneSize}
        separatorLabel={separatorLabel}
      />
    </div>
  )
}

export { AppShellWorkspace, type AppShellWorkspaceProps }
